export const meta = {
  name: "isoline-scene",
  version: "1.0.0",
  category: "3d-hero",
  tags: ["svg", "isometric", "line-art", "illustration", "interactive", "cursor", "dark", "hero", "orange"],
  summary:
    "Split hero with Isoline's animated isometric scene beside the copy: a mechanical keyboard drawn in SVG hairlines that types by itself while keys dip under the pointer, on a fading grid floor.",
  needs: [],
  license: "MIT",
  // Knob ranges live in meta.json; this mirrors names and defaults.
  options: {
    scene: { type: "string", default: "keyboard", description: "city, supply, flight, delivery, port, line, product, steamer, cabinet, lockers, keyboard, interface, relief or word." },
    azimuth: { type: "number", default: 30, description: "Camera turn in degrees." },
    elevation: { type: "number", default: 36, description: "Camera tilt in degrees." },
    accent: { type: "string", default: "#ff6a3d", description: "What moves or answers the pointer." },
    plate: { type: "string", default: "#08090a", description: "Ground colour, the stage background." },
    hi: { type: "string", default: "#d0d6e0", description: "Lit lines." },
    floor: { type: "string", default: "grid", description: "Floor under the scene: none, grid or dots." },
    floorStrength: { type: "number", default: 0.5, description: "0 faint to 1 strong." },
    density: { type: "number", default: 0.5, description: "0 to 1, read by each scene its own way." },
    speed: { type: "number", default: 1, description: "Animation speed." },
    stroke: { type: "number", default: 0.9, description: "Line width in px." },
    spin: { type: "boolean", default: false, description: "Turntable: the camera circles the scene." },
    parallax: { type: "boolean", default: true, description: "The camera leans a little towards the pointer." },
    interactive: { type: "boolean", default: true, description: "The scene answers the pointer." },
    labels: { type: "boolean", default: true, description: "Labels and callouts." },
  },
  origin: {
    repo: "JuPicker/isoline",
    commit: "77c1da5798138cb2ae82842b7734867beba95828",
    path: ["isoline.min.js", "examples/basic.html"],
  },
};

let Isoline = null;
const DEFAULTS = Object.fromEntries(Object.entries(meta.options).map(([k, v]) => [k, v.default]));

export function mount(el, opts = {}) {
  const resting = { update() {}, destroy() {} };
  if (!el || typeof window === "undefined" || typeof document === "undefined") return resting;
  const frame = el.querySelector(".fx-isoline-scene__frame");
  if (!frame) return resting;
  if (!Isoline) Isoline = isolineLib(window);

  // Upstream fills the element it is given and writes role, aria-label, its
  // --il-* palette and a background onto it; a stage this module owns keeps
  // all of that off the section and goes away whole on destroy().
  const stage = document.createElement("div");
  stage.className = "fx-isoline-scene__stage";
  frame.append(stage);
  const iso = new Isoline(stage, { ...DEFAULTS, ...opts });
  el.setAttribute("data-fx-live", "");

  let stopped = false;
  return {
    update(next = {}) {
      if (stopped) return;
      iso.set(next);
    },
    destroy() {
      if (stopped) return;
      stopped = true;
      iso.destroy();
      stage.remove();
      el.removeAttribute("data-fx-live");
    },
  };
}
